<template>
  <Teleport to="body">
    <Transition name="me-busy">
      <div v-if="task" class="me-busy-mask meta-editor-scope" role="alertdialog" aria-busy="true">
        <div class="me-busy-card">
          <div class="me-busy-spinner">
            <Loader2 :size="22" class="me-busy-spin-icon" />
          </div>
          <div class="me-busy-title">{{ task.title }}</div>
          <div v-if="task.detail" class="me-busy-detail">{{ task.detail }}</div>

          <!-- 进度条：percent 已知 → 实进度，未知 → indeterminate 条纹动画 -->
          <div class="me-busy-progress" :class="{ indeterminate: task.percent == null }">
            <div
              class="me-busy-bar"
              :style="task.percent != null ? { width: `${clamp(task.percent)}%` } : undefined"
            ></div>
          </div>
          <div v-if="task.percent != null" class="me-busy-percent">
            {{ Math.round(clamp(task.percent)) }}%
          </div>
        </div>
      </div>
    </Transition>
  </Teleport>
</template>

<script lang="ts">
/**
 * 全局 BusyOverlay 单例：
 *
 * - `beginBusy(opts)` 开启遮罩，返回一个 handle，用于后续 update / end
 * - 同一时刻只展示一个任务；嵌套调用按"栈"模型（end 后自动恢复上一个）
 *
 * 用法：
 * ```ts
 * const handle = beginBusy({ title: '导出中', percent: 0 });
 * try {
 *   for (let i = 0; i < total; i++) {
 *     handle.update({ percent: ((i + 1) / total) * 100, detail: `${i + 1}/${total}` });
 *   }
 * } finally {
 *   handle.end();
 * }
 * ```
 */
import { ref } from 'vue';
import { Loader2 } from 'lucide-vue-next';

export interface BusyTask {
  id: number;
  title: string;
  detail?: string;
  /** 0~100；为 null/undefined 时显示 indeterminate 条纹动画 */
  percent?: number | null;
}

export interface BusyHandle {
  /** 更新已存在任务的 title/detail/percent（部分更新） */
  update(patch: Partial<Omit<BusyTask, 'id'>>): void;
  /** 结束此任务（出栈） */
  end(): void;
}

/** 任务栈：栈顶始终是当前显示的；end 后弹出，下一个自然显示 */
const _stack = ref<BusyTask[]>([]);
let _idSeed = 1;

export function beginBusy(opts: Omit<BusyTask, 'id'>): BusyHandle {
  const id = _idSeed++;
  const task: BusyTask = { id, ...opts };
  _stack.value.push(task);

  let ended = false;
  return {
    update(patch) {
      if (ended) return;
      const idx = _stack.value.findIndex((t) => t.id === id);
      if (idx < 0) return;
      _stack.value[idx] = { ..._stack.value[idx], ...patch };
    },
    end() {
      if (ended) return;
      ended = true;
      const idx = _stack.value.findIndex((t) => t.id === id);
      if (idx >= 0) _stack.value.splice(idx, 1);
    },
  };
}

/** 内部钩子：组件 setup 与外部 helpers 共享同一个 ref */
export function _useBusyStack() {
  return _stack;
}
</script>

<script setup lang="ts">
import { computed } from 'vue';

const stack = _useBusyStack();
/** 当前显示的任务始终是栈顶 */
const task = computed<BusyTask | null>(() =>
  stack.value.length > 0 ? stack.value[stack.value.length - 1] : null,
);

const clamp = (v: number) => Math.max(0, Math.min(100, v));
</script>

